<?php $pageTitle='Flower listings';require __DIR__.'/_top.php';$pdo=db();if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$action=$_POST['action']??'';if($action==='save'){$id=(int)($_POST['id']??0);$data=[trim($_POST['name']),trim($_POST['category']),(float)$_POST['price'],trim($_POST['unit']),(int)$_POST['quantity'],trim($_POST['image_url']),$_POST['status']==='active'?'active':'inactive'];if($id){$pdo->prepare("UPDATE flowers SET name=?,category=?,price=?,unit=?,quantity=?,image_url=?,status=? WHERE id=?")->execute([...$data,$id]);}else{$pdo->prepare("INSERT INTO flowers(name,category,price,unit,quantity,image_url,status) VALUES(?,?,?,?,?,?,?)")->execute($data);}flash('Flower listing saved.');header('Location: '.url('admin/flowers.php'));exit;}if($action==='delete'){$pdo->prepare("DELETE FROM flowers WHERE id=?")->execute([(int)$_POST['id']]);flash('Flower listing deleted.');header('Location: '.url('admin/flowers.php'));exit;}}
$edit=null;if(isset($_GET['edit'])){$s=$pdo->prepare("SELECT * FROM flowers WHERE id=?");$s->execute([(int)$_GET['edit']]);$edit=$s->fetch();}$rows=$pdo->query("SELECT * FROM flowers ORDER BY created_at DESC")->fetchAll();$f=get_flash(); ?>
<?php if($f): ?><p class="notice"><?= e($f[0]) ?></p><?php endif; ?><div class="admin-columns"><section class="panel"><div class="panel-heading"><h2><?= $edit?'Edit listing':'Add a flower' ?></h2></div><form method="post" class="admin-form"><input type="hidden" name="csrf" value="<?= csrf_token() ?>"><input type="hidden" name="action" value="save"><input type="hidden" name="id" value="<?= (int)($edit['id']??0) ?>"><label>Flower name<input required name="name" value="<?= e($edit['name']??'') ?>"></label><label>Category<input required name="category" value="<?= e($edit['category']??'') ?>" placeholder="Roses"></label><div class="form-row"><label>Price (₹)<input required type="number" step=".01" min="0" name="price" value="<?= e((string)($edit['price']??'')) ?>"></label><label>Unit<input name="unit" value="<?= e($edit['unit']??'bunch') ?>"></label></div><label>Quantity<input type="number" min="0" name="quantity" value="<?= e((string)($edit['quantity']??0)) ?>"></label><label>Image URL<input name="image_url" value="<?= e($edit['image_url']??'') ?>"></label><label>Status<select name="status"><option value="active" <?= ($edit['status']??'active')==='active'?'selected':'' ?>>Active</option><option value="inactive" <?= ($edit['status']??'')==='inactive'?'selected':'' ?>>Inactive</option></select></label><button class="btn btn-primary">Save listing</button><?php if($edit): ?><a class="back-link" href="<?= url('admin/flowers.php') ?>">Cancel edit</a><?php endif; ?></form></section><section class="panel"><div class="panel-heading"><div><span class="eyebrow">CATALOGUE</span><h2>All flower listings</h2></div><span class="status"><?= count($rows) ?> total</span></div><div class="table-wrap"><table><thead><tr><th>Flower</th><th>Price</th><th>Qty</th><th>Status</th><th>Actions</th></tr></thead><tbody><?php foreach($rows as $r): ?><tr><td><b><?= e($r['name']) ?></b><small class="subline"><?= e($r['category']) ?></small></td><td>₹<?= number_format((float)$r['price'],2) ?></td><td><?= (int)$r['quantity'] ?></td><td><?= e($r['status']) ?></td><td><a href="?edit=<?= (int)$r['id'] ?>">Edit</a><form method="post" class="inline-form" onsubmit="return confirm('Delete this listing?')"><input type="hidden" name="csrf" value="<?= csrf_token() ?>"><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?= (int)$r['id'] ?>"><button class="link-danger">Delete</button></form></td></tr><?php endforeach; ?><?php if(!$rows): ?><tr><td colspan="5">No listings yet.</td></tr><?php endif; ?></tbody></table></div></section></div><?php require __DIR__.'/_bottom.php'; ?>
